MOD = 10**9 + 7

def count_variants(words):
    n = len(words)
    dp = [[0] * 26 for _ in range(n + 1)]

    for j in range(26):
        dp[0][j] = 1

    for i in range(1, n + 1):
        for j in range(26):
            dp[i][j] = dp[i - 1][j]
            for k in range(26):
                if j >= k:
                    dp[i][j] = (dp[i][j] + dp[i - 1][k]) % MOD

    result = 0
    for j in range(26):
        result = (result + dp[n][j]) % MOD

    return result

# Read input
n = int(input())
words = [input().strip() for _ in range(n)]

# Output the result
print(count_variants(words))
